create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, store text not null default 'apple-japan', name text not null, model text, color text, capacity text, sku text, official_url text not null, target_price integer, currency text not null default 'JPY', quantity integer not null default 1 check (quantity > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.purchase_tasks (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete restrict, quantity integer not null default 1 check (quantity > 0), max_price integer, status text not null default 'queued' check (status in ('queued','running','paused','waiting_approval','handoff','completed','failed','cancelled')), idempotency_key text not null unique, start_time timestamptz, last_event text, error_message text, retry_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.task_events (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.purchase_tasks(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, event_type text not null, message text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.worker_heartbeats (worker_id text primary key, owner_id uuid references auth.users(id) on delete cascade, status text not null default 'online', last_seen_at timestamptz not null default now(), metadata jsonb not null default '{}');
create table if not exists public.notification_channels (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, channel_type text not null default 'discord', webhook_secret text not null, enabled boolean not null default true, created_at timestamptz not null default now());
create index if not exists purchase_tasks_owner_status_idx on public.purchase_tasks(owner_id,status); create index if not exists task_events_task_created_idx on public.task_events(task_id,created_at desc); create index if not exists worker_heartbeats_seen_idx on public.worker_heartbeats(last_seen_at);
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.purchase_tasks enable row level security; alter table public.task_events enable row level security; alter table public.worker_heartbeats enable row level security; alter table public.notification_channels enable row level security;
create policy "own profile" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "own products" on public.products for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "own tasks" on public.purchase_tasks for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "own events" on public.task_events for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "own heartbeats" on public.worker_heartbeats for select using (owner_id = auth.uid());
create policy "own channels" on public.notification_channels for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
